// ============================================================================
// SPI_Host_apb: APB4 register wrapper around SPI_Host_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/SPI_Host.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/SPI_Host.md
// ============================================================================
module SPI_Host_apb #(
  parameter int NCS = 2
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic sclk,
  output logic mosi,
  input logic miso,
  output logic [NCS-1:0] csn
);
  localparam logic [31:0] ID_VALUE = 32'h5C520100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [10:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd11) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [15:0]   c_div;
  logic          c_cpol;
  logic          c_cpha;
  logic [1:0]    c_cs;
  logic [7:0]    c_tx_data;
  logic          c_start;
  logic [7:0]    c_rx_data;
  logic          c_busy;
  logic          c_done;
  SPI_Host_top #(.NCS(NCS)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .sclk(sclk),
    .mosi(mosi),
    .miso(miso),
    .csn(csn),
    .div(c_div),
    .cpol(c_cpol),
    .cpha(c_cpha),
    .cs(c_cs),
    .tx_data(c_tx_data),
    .start(c_start),
    .rx_data(c_rx_data),
    .busy(c_busy),
    .done(c_done)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [3:0] r_CFG;   // 12'h014 CFG
  logic [15:0] r_DIV;   // 12'h018 DIV
  logic [7:0] r_TX_DATA;   // 12'h01C TX_DATA
  logic [0:0] p_CMD;   // 12'h020 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CFG <= 4'h0;
      r_DIV <= 16'h9;
      r_TX_DATA <= 8'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CFG <= (r_CFG & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      if (wr && hit[6]) r_DIV <= (r_DIV & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[7]) r_TX_DATA <= (r_TX_DATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      p_CMD <= (wr && hit[8]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_cpol = r_CFG[0:0];
  assign c_cpha = r_CFG[1:1];
  assign c_cs = r_CFG[3:2];
  assign c_div = r_DIV[15:0];
  assign c_tx_data = r_TX_DATA[7:0];
  assign c_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CFG);
      10'd6: apb_rdata = 32'(r_DIV);
      10'd7: apb_rdata = 32'(r_TX_DATA);
      10'd9: apb_rdata = 32'({c_rx_data});
      10'd10: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
